// --- Vue (MVVM 风格：响应式状态 + computed 派生 + v-model) ---
const query = ref('')
const visibleCourses = computed(() =>
  courses.filter(c => c.name.includes(query.value))
)
// 模板绑定：<input v-model="query">
// 等价于：<input :value="query" @input="query = $event.target.value">

// --- React (状态快照风格：Render 期直接计算派生值 + 受控输入框) ---
function CourseList({ courses }) {
  const [query, setQuery] = useState('')
  // 派生列表直接由本轮快照算出，绝不另存为独立 useState
  const visibleCourses = courses.filter(c => c.name.includes(query))
  return (
    <input
      value={query}
      onChange={e => setQuery(e.target.value)}
    />
  )
}
